import pickle
import json
from threading import Lock

class SessionCache:
    def __init__(self, max_size=10000):
        self.cache = {}
        self.lock = Lock()
        self.max_size = max_size

    def set(self, session_id, user_data):
        """Store user session object directly for maximum speed."""
        with self.lock:
            if len(self.cache) >= self.max_size:
                # Remove oldest entry
                self.cache.pop(next(iter(self.cache)))
            self.cache[session_id] = user_data

    def get(self, session_id):
        """Retrieve session object in O(1) time."""
        with self.lock:
            return self.cache.get(session_id)

    def load_from_file(self, filepath):
        """Load cached sessions from disk for faster startup."""
        try:
            with open(filepath, 'rb') as f:
                self.cache = pickle.load(f)
        except Exception:
            pass

    def save_to_file(self, filepath):
        """Persist cache to disk."""
        with open(filepath, 'wb') as f:
            pickle.dump(self.cache, f)

# Usage
cache = SessionCache()
cache.load_from_file('/tmp/sessions.pkl')

